    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Refactor Cloud Foundry Deployer with CF Java Client",
      "activity_description": "Refactor the Cloud Foundry SPI deployer implementation using the official CF Java client, replacing legacy code, improving async performance, and writing integration tests.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "ACT-6",
